@extends('layouts.app') @section('header','Live Tracking Monitor') @section('content')<h1 class="page-title">Live Tracking</h1><p class="muted">Active trips and the most recent GPS point received by the system.</p><div class="grid two"><div class="card"><div id="map" class="map"></div></div><div class="card"><table><tr><th>Bus</th><th>Route</th><th>Last Update</th></tr>@foreach($trips as $t)<tr><td>{{$t->bus?->bus_number}}</td><td>{{$t->route?->name}}</td><td>{{$t->liveLocation?->recorded_at?->diffForHumans()??'No GPS yet'}}</td></tr>@endforeach</table></div></div>@endsection @push('head')<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">@endpush @push('scripts')<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const map=L.map('map').setView([7.8731,80.7718],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);const pts=@json($trips->filter(fn($t)=>$t->liveLocation)->map(fn($t)=>['lat'=>(float)$t->liveLocation->latitude,'lng'=>(float)$t->liveLocation->longitude,'bus'=>$t->bus?->bus_number,'route'=>$t->route?->name])->values());pts.forEach(p=>L.marker([p.lat,p.lng]).addTo(map).bindPopup(`<b>${p.bus}</b><br>${p.route}`));</script>@endpush